svg.script:
(() => {
  const SVG_NS = "http://www.w3.org/2000/svg";
  const root = document.documentElement;
  const regular = document.getElementById("regularFrame");
  const transparent = document.getElementById("transparentFrame");
  const contents = document.getElementById("contents");

  const ANCHORS = [[430, 455, 170, -8], [620, 470, 165, 7], [810, 450, 160, -5], [520, 540, 155, 10], [710, 545, 155, -11], [910, 520, 145, 4], [345, 545, 145, -3], [620, 600, 140, 8], [780, 605, 135, -7], [470, 615, 135, 5], [905, 590, 130, -9], [300, 610, 125, 6]];
  const PATHS = {
    ingredient: "../ingredients/",
    trash: "../junk/",
    junk: "../junk/"
  };

  const state = {
    items: [],
    switchAt: 4
  };

  function sanitizeFile(file) {
    return String(file || "").replace(/^.*[\\/]/, "");
  }

  function resolveSource(kind, fileOrUrl) {
    const value = String(fileOrUrl || "");
    if (/^(?:https?:|data:|blob:|\.\.?\/)/i.test(value)) return value;
    const folder = kind === "trash" || kind === "junk" ? PATHS.trash : PATHS.ingredient;
    return folder + sanitizeFile(value);
  }

  function frameForCount() {
    const useTransparent = state.items.length >= state.switchAt;
    regular.setAttribute("opacity", useTransparent ? "0" : "1");
    transparent.setAttribute("opacity", useTransparent ? "1" : "0");
    root.setAttribute("data-frame", useTransparent ? "transparent-inside" : "regular");
    root.setAttribute("data-count", String(state.items.length));
    return useTransparent ? "transparent-inside" : "regular";
  }

  function notify() {
    const payload = {
      type: "container-flipbook:state",
      id: root.id,
      container: "basket",
      count: state.items.length,
      switchAt: state.switchAt,
      frame: frameForCount(),
      items: state.items.map(x => ({ kind: x.kind, file: x.file }))
    };
    try {
      window.parent.postMessage(payload, "*");
    } catch (_) {}
    root.dispatchEvent(new CustomEvent("flipbookstate", { detail: payload }));
  }

  function addItem(kind, fileOrUrl, options = {}) {
    kind = kind === "trash" || kind === "junk" ? "trash" : "ingredient";
    const index = state.items.length;
    const anchor = ANCHORS[index % ANCHORS.length];
    const cycle = Math.floor(index / ANCHORS.length);
    const x = anchor[0] + ((cycle % 3) - 1) * 22;
    const y = anchor[1] - Math.min(cycle * 24, 90);
    const size = Math.max(90, anchor[2] - Math.min(cycle * 7, 42));
    const rotation = anchor[3] + ((index * 7) % 13) - 6;

    const img = document.createElementNS(SVG_NS, "image");
    const src = resolveSource(kind, fileOrUrl);
    img.setAttribute("href", src);
    img.setAttributeNS("http://www.w3.org/1999/xlink", "xlink:href", src);
    img.setAttribute("x", String(x - size / 2));
    img.setAttribute("y", "-240");
    img.setAttribute("width", String(options.width || size));
    img.setAttribute("height", String(options.height || size));
    img.setAttribute("preserveAspectRatio", "xMidYMid meet");
    img.setAttribute("transform", `rotate(${rotation} ${x} ${y})`);
    img.setAttribute("data-kind", kind);
    img.setAttribute("data-file", sanitizeFile(fileOrUrl));

    const drop = document.createElementNS(SVG_NS, "animate");
    drop.setAttribute("attributeName", "y");
    drop.setAttribute("from", "-240");
    drop.setAttribute("to", String(y - size / 2));
    drop.setAttribute("dur", String(options.duration || 0.42));
    drop.setAttribute("begin", "0s");
    drop.setAttribute("fill", "freeze");
    drop.setAttribute("calcMode", "spline");
    drop.setAttribute("keySplines", "0.22 0.75 0.28 1");
    img.appendChild(drop);

    contents.appendChild(img);
    state.items.push({ kind, file: sanitizeFile(fileOrUrl), src, node: img });
    frameForCount();
    notify();
    return state.items.length;
  }

  function addIngredient(fileOrUrl, options) {
    return addItem("ingredient", fileOrUrl, options);
  }

  function addTrash(fileOrUrl, options) {
    return addItem("trash", fileOrUrl, options);
  }

  function removeLast() {
    const last = state.items.pop();
    if (last && last.node && last.node.parentNode) last.node.remove();
    frameForCount();
    notify();
    return state.items.length;
  }

  function reset() {
    state.items.length = 0;
    while (contents.firstChild) contents.removeChild(contents.firstChild);
    frameForCount();
    notify();
  }

  function setSwitchAt(count) {
    const n = Math.max(1, Number(count) || 4);
    state.switchAt = n;
    frameForCount();
    notify();
    return n;
  }

  function setItems(items = []) {
    reset();
    for (const item of items) {
      if (!item) continue;
      addItem(item.kind || item.type || "ingredient", item.file || item.src || item.url, item.options || {});
    }
    return state.items.length;
  }

  function getState() {
    return {
      container: "basket",
      count: state.items.length,
      switchAt: state.switchAt,
      frame: state.items.length >= state.switchAt ? "transparent-inside" : "regular",
      items: state.items.map(x => ({ kind: x.kind, file: x.file, src: x.src }))
    };
  }

  // Public API when loaded via <object>, <iframe>, or inline SVG.
  window.Flipbook = {
    addItem,
    addIngredient,
    addTrash,
    removeLast,
    reset,
    setItems,
    setSwitchAt,
    getState
  };

  // Parent-page integration:
  // object.contentWindow.postMessage({type:"container-flipbook:add",kind:"ingredient",file:"bacon.svg"},"*")
  window.addEventListener("message", (event) => {
    const d = event.data || {};
    if (d.target && d.target !== root.id && d.target !== "basket") return;
    if (d.type === "container-flipbook:add") addItem(d.kind || "ingredient", d.file || d.src, d.options || {});
    if (d.type === "container-flipbook:remove-last") removeLast();
    if (d.type === "container-flipbook:reset") reset();
    if (d.type === "container-flipbook:set-items") setItems(d.items || []);
    if (d.type === "container-flipbook:set-switch-at") setSwitchAt(d.count);
  });

  frameForCount();
})();
